def minimum_operations(t, test_cases):
    results = []
    for a, b in test_cases:
        if a > b:
            a, b = b, a
        operations = 0
        while a != b:
            if b - a >= a:
                b -= a
                operations += 1
            else:
                operations += (b - a)
                a = b
        results.append(operations)
    return results

